#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)] // integration-test crate
//! MaxMind DB GeoIP (RSK-05, K-98) and impossible travel through it
//! (RSK-02). Fixtures are generated by `authn_testkit::mmdb` (no
//! third-party GeoIP data in the repository).

use std::net::IpAddr;
use std::path::{Path, PathBuf};
use std::sync::Arc;
use std::time::Duration;

use authn_core::config::protect::RiskConfig;
use authn_core::domain::{AccountStatus, EmailAddress, LoginMethod};
use authn_core::id::UserId;
use authn_core::ports::{
    Clock, GeoIpLookup, GeoLocation, RateLimiter, RiskEvaluator, RiskInput, RiskLevel, RiskReason,
};
use authn_crypto::kdf::KeyRing;
use authn_protect::KeyHasher;
use authn_protect::rate_limit::MemoryRateLimiter;
use authn_protect::risk::{DefaultRiskEvaluator, MmdbGeoIp};
use authn_store::{NewUser, UserRepository};
use authn_testkit::TestPorts;
use authn_testkit::mmdb::{MmdbBuilder, city_record, country_record};
use sqlx::PgPool;

const ISTANBUL_IP: &str = "81.214.10.20";
const ISTANBUL_V6: &str = "2a02:ff0:1::1";
const LONDON_IP: &str = "2.24.10.20";
const ANKARA_IP: &str = "88.230.5.6";
const COUNTRY_ONLY_IP: &str = "5.6.7.8";
const UNKNOWN_IP: &str = "9.9.9.9";
const DEVICE: &str = "laptop-device-000000001";

/// A fresh directory under the system temp dir (removed by [`TempDir`]).
struct TempDir(PathBuf);

impl TempDir {
    fn new() -> Self {
        let dir = std::env::temp_dir().join(format!("authn-geoip-{}", uuid::Uuid::now_v7()));
        std::fs::create_dir_all(&dir).unwrap();
        Self(dir)
    }

    fn path(&self, name: &str) -> PathBuf {
        self.0.join(name)
    }
}

impl Drop for TempDir {
    fn drop(&mut self) {
        let _ = std::fs::remove_dir_all(&self.0);
    }
}

fn database() -> MmdbBuilder {
    MmdbBuilder::new("Test-City")
        .insert("81.214.0.0/16", city_record("TR", "Istanbul", 41.0082, 28.9784, 20))
        .insert("2a02:ff0::/32", city_record("TR", "Istanbul", 41.0082, 28.9784, 20))
        .insert("2.24.0.0/16", city_record("GB", "London", 51.5074, -0.1278, 20))
        .insert("88.230.0.0/16", city_record("TR", "Ankara", 39.9334, 32.8597, 20))
        .insert("5.6.0.0/16", country_record("DE"))
        // Non-public ranges that a sloppy database might still carry: the
        // adapter must refuse them before looking them up.
        .insert("10.0.0.0/8", city_record("GB", "London", 51.5074, -0.1278, 5))
        .insert("192.168.0.0/16", city_record("GB", "London", 51.5074, -0.1278, 5))
        .insert("100.64.0.0/10", city_record("GB", "London", 51.5074, -0.1278, 5))
        .insert("203.0.113.0/24", city_record("GB", "London", 51.5074, -0.1278, 5))
        .insert("fc00::/7", city_record("GB", "London", 51.5074, -0.1278, 5))
}

fn write(path: &Path, builder: &MmdbBuilder) {
    std::fs::write(path, builder.build()).unwrap();
}

fn ip(s: &str) -> IpAddr {
    s.parse().unwrap()
}

#[tokio::test]
async fn rsk_05_mmdb_lookup_returns_only_a_coarse_location() {
    let dir = TempDir::new();
    let path = dir.path("city.mmdb");
    write(&path, &database());
    let geo = MmdbGeoIp::open(&path).unwrap();
    assert_eq!(geo.info().database_type, "Test-City");
    assert_eq!(geo.info().ip_version, 6);

    let expected = GeoLocation {
        country_code: Some("TR".to_owned()),
        city: Some("Istanbul".to_owned()),
        // 41.0082, 28.9784 rounded to 0.1° (data minimisation).
        latitude: Some(41.0),
        longitude: Some(29.0),
        // 20 km + rounding error.
        accuracy_km: Some(28),
    };
    assert_eq!(
        geo.lookup(ip(ISTANBUL_IP)).await.unwrap(),
        Some(expected.clone())
    );
    assert_eq!(
        geo.lookup(ip(ISTANBUL_V6)).await.unwrap(),
        Some(expected.clone())
    );
    // An IPv4-mapped IPv6 address is the IPv4 address.
    assert_eq!(
        geo.lookup(ip("::ffff:81.214.10.20")).await.unwrap(),
        Some(expected)
    );
    // Country-level record: no coordinates, so no travel signal later.
    let country = geo.lookup(ip(COUNTRY_ONLY_IP)).await.unwrap().unwrap();
    assert_eq!(country.country_code.as_deref(), Some("DE"));
    assert_eq!(
        (
            country.city,
            country.latitude,
            country.longitude,
            country.accuracy_km
        ),
        (None, None, None, None)
    );
}

#[tokio::test]
async fn rsk_05_unknown_private_and_reserved_addresses_have_no_location() {
    let dir = TempDir::new();
    let path = dir.path("city.mmdb");
    write(&path, &database());
    let geo = MmdbGeoIp::open(&path).unwrap();
    for addr in [
        UNKNOWN_IP,
        "10.1.2.3",
        "192.168.1.1",
        "100.64.1.1",
        "127.0.0.1",
        "169.254.1.1",
        "203.0.113.7",
        "0.0.0.0",
        "255.255.255.255",
        "::1",
        "::",
        "fe80::1",
        "fd00::1",
        "2001:db8::1",
        "::ffff:10.1.2.3",
    ] {
        assert_eq!(geo.lookup(ip(addr)).await.unwrap(), None, "{addr}");
    }
}

#[tokio::test]
async fn rsk_05_reload_swaps_a_changed_file_and_keeps_the_old_one_on_failure() {
    let dir = TempDir::new();
    let path = dir.path("city.mmdb");
    write(&path, &database());
    let geo = MmdbGeoIp::open(&path).unwrap();
    assert!(!geo.reload_if_changed().unwrap(), "unchanged file");

    // A newer database (atomic replace, as an updater does): Istanbul's
    // range moves to Berlin.
    let next = dir.path("next.mmdb");
    write(
        &next,
        &MmdbBuilder::new("Test-City-v2")
            .build_epoch(1_767_312_000)
            .insert(
                "81.214.0.0/16",
                city_record("DE", "Berlin", 52.52, 13.405, 10),
            ),
    );
    std::fs::rename(&next, &path).unwrap();
    assert!(geo.reload_if_changed().unwrap());
    assert_eq!(geo.info().database_type, "Test-City-v2");
    let berlin = geo.lookup(ip(ISTANBUL_IP)).await.unwrap().unwrap();
    assert_eq!(berlin.country_code.as_deref(), Some("DE"));

    // A corrupt replacement is refused; the loaded database stays in use.
    std::fs::write(&path, b"truncated download").unwrap();
    assert!(geo.reload_if_changed().is_err());
    assert_eq!(geo.info().database_type, "Test-City-v2");
    assert!(geo.lookup(ip(ISTANBUL_IP)).await.unwrap().is_some());

    // A deleted file: error, old database kept.
    std::fs::remove_file(&path).unwrap();
    assert!(geo.reload_if_changed().is_err());
    assert!(geo.lookup(ip(ISTANBUL_IP)).await.unwrap().is_some());
}

#[test]
fn rsk_05_truncated_database_is_refused_at_startup() {
    let dir = TempDir::new();
    let bytes = database().build();
    let path = dir.path("truncated.mmdb");
    // Cut inside the search tree: the metadata marker is gone.
    std::fs::write(&path, &bytes[..bytes.len() / 3]).unwrap();
    assert!(MmdbGeoIp::open(&path).is_err());
    // Search tree pointing past the data section.
    let mut corrupt = bytes.clone();
    corrupt[0..3].copy_from_slice(&[0xff, 0xff, 0xff]);
    std::fs::write(&path, &corrupt).unwrap();
    assert!(MmdbGeoIp::open(&path).is_err());
}

struct Fixture {
    ports: TestPorts,
    evaluator: DefaultRiskEvaluator,
    pool: PgPool,
    _dir: TempDir,
}

impl Fixture {
    fn new(pool: &PgPool) -> Self {
        let ports = TestPorts::new();
        let hasher = KeyHasher::new(&KeyRing::derive(&[6_u8; 32]).unwrap()).unwrap();
        let limiter: Arc<dyn RateLimiter> =
            Arc::new(MemoryRateLimiter::new(ports.clock.clone(), hasher.clone()));
        let dir = TempDir::new();
        let path = dir.path("city.mmdb");
        write(&path, &database());
        let geo: Arc<dyn GeoIpLookup> = Arc::new(MmdbGeoIp::open(&path).unwrap());
        let evaluator = DefaultRiskEvaluator::new(
            pool.clone(),
            hasher,
            limiter,
            &RiskConfig::default(),
            Some(geo),
        )
        .unwrap();
        Self {
            ports,
            evaluator,
            pool: pool.clone(),
            _dir: dir,
        }
    }

    async fn user(&self) -> UserId {
        let mut conn = self.pool.acquire().await.unwrap();
        UserRepository::create(
            &mut conn,
            &NewUser {
                id: UserId::generate(),
                email: EmailAddress::parse("traveller@example.com").unwrap(),
                status: AccountStatus::Active,
                created_at: self.ports.clock.now(),
            },
        )
        .await
        .unwrap()
        .id
    }

    fn input(&self, user: UserId, addr: &str) -> RiskInput {
        RiskInput {
            user_id: Some(user),
            ip: ip(addr),
            user_agent: None,
            device_id: Some(DEVICE.to_owned()),
            at: self.ports.clock.now(),
            method: LoginMethod::Password,
        }
    }

    async fn travel_flagged(&self, user: UserId, addr: &str) -> bool {
        self.evaluator
            .evaluate(&self.input(user, addr))
            .await
            .unwrap()
            .reasons
            .contains(&RiskReason::ImpossibleTravel)
    }
}

#[sqlx::test(migrator = "authn_testkit::MIGRATOR")]
async fn rsk_05_impossible_travel_through_the_mmdb_reader(pool: PgPool) {
    let f = Fixture::new(&pool);
    let user = f.user().await;
    f.evaluator
        .record_successful_login(&f.input(user, ISTANBUL_IP))
        .await
        .unwrap();

    // Only coarse coordinates are stored (KVKK data minimisation).
    let (lat, lon, country): (Option<f64>, Option<f64>, Option<String>) = sqlx::query_as(
        "SELECT last_latitude, last_longitude, last_country FROM known_devices WHERE user_id = $1",
    )
    .bind(user)
    .fetch_one(&pool)
    .await
    .unwrap();
    assert_eq!(
        (lat, lon, country.as_deref()),
        (Some(41.0), Some(29.0), Some("TR"))
    );

    // Istanbul → London (~2500 km) in one hour: impossible.
    f.ports.clock.advance(Duration::from_secs(3600));
    let assessed = f
        .evaluator
        .evaluate(&f.input(user, LONDON_IP))
        .await
        .unwrap();
    assert!(assessed.reasons.contains(&RiskReason::ImpossibleTravel));
    assert_eq!(assessed.level, RiskLevel::High);
    // Istanbul → Ankara (~350 km) in one hour: possible.
    assert!(!f.travel_flagged(user, ANKARA_IP).await);
    // Unknown, country-only, private and reserved sources: no signal.
    for addr in [
        UNKNOWN_IP,
        COUNTRY_ONLY_IP,
        "10.1.2.3",
        "192.168.1.1",
        "203.0.113.7",
        "::1",
    ] {
        assert!(!f.travel_flagged(user, addr).await, "{addr}");
    }
    // London is plausible after seven hours.
    f.ports.clock.advance(Duration::from_secs(6 * 3600));
    assert!(!f.travel_flagged(user, LONDON_IP).await);
}

#[sqlx::test(migrator = "authn_testkit::MIGRATOR")]
async fn rsk_05_login_from_a_private_address_keeps_the_last_public_fix(pool: PgPool) {
    let f = Fixture::new(&pool);
    let user = f.user().await;
    f.evaluator
        .record_successful_login(&f.input(user, ISTANBUL_IP))
        .await
        .unwrap();
    // A later login over the office VPN (private address) has no location
    // and must not erase the last known one...
    f.ports.clock.advance(Duration::from_secs(600));
    f.evaluator
        .record_successful_login(&f.input(user, "10.1.2.3"))
        .await
        .unwrap();
    // ...so a jump to London right after is still caught.
    f.ports.clock.advance(Duration::from_secs(600));
    assert!(f.travel_flagged(user, LONDON_IP).await);
}
